import{C as e,L as t,S as n,V as r,X as i,_ as a,b as o,x as s}from"./vue-Vea_iehr.js";import{oi as c}from"./common-BkM8iD8A.js";var l=JSON.parse(`{"path":"/router/routeros/hn6upvnt/","title":"设置DHCPv4 | RouterOS","lang":"zh-CN","frontmatter":{"title":"设置DHCPv4","createTime":"2026/08/25 13:51:48","permalink":"/router/routeros/hn6upvnt/","copyright":{"creation":"reprint","license":"CC-BY-4.0","source":"https://gitee.com/callmer/routeros_toss_notes/tree/master","author":{"name":"callmer","url":"https://gitee.com/callmer"}}},"readingTime":{"minutes":4.07,"words":1220},"git":{},"filePathRelative":"router/routeros/04.设置DHCPv4.md","headers":[]}`),u={name:`04.设置DHCPv4.md`};function d(c,l,u,d,f,p){let m=r(`VPLink`);return t(),o(`div`,null,[l[3]||=a(`h2`,{id:`_1-设置-dhcpv4`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#_1-设置-dhcpv4`},[a(`span`,null,`1.设置 DHCPv4`)])],-1),a(`p`,null,[l[1]||=n(`在上一篇文章 `,-1),e(m,{href:`./03.%E8%AE%BE%E7%BD%AEDNS.md`},{default:i(()=>[...l[0]||=[n(`03.设置DNS`,-1)]]),_:1}),l[2]||=n(` 中，已经设置了系统 DNS ，现在开始设置系统 DHCPv4 。`,-1)]),l[4]||=s(`<p>设置 IPv4 DHCP 服务器包括两个部分，创建 DHCPv4 的地址池和创建 DHCPv4 服务器。</p><h3 id="_1-1-创建-dhcpv4-地址池" tabindex="-1"><a class="header-anchor" href="#_1-1-创建-dhcpv4-地址池"><span>1.1.创建 DHCPv4 地址池</span></a></h3><p>先创建 DHCPv4 地址池，点击左侧导航 <code>IP</code> 菜单的子菜单 <code>Pool</code> ，点击 <code>New</code> 。</p><table><thead><tr><th>参数</th><th>值</th></tr></thead><tbody><tr><td>Name</td><td><code>dhcpv4-pool1</code></td></tr><tr><td>Addresses</td><td><code>172.16.1.100-172.16.1.200</code></td></tr><tr><td>Comment</td><td><code>defconf: local LAN DHCPv4 pool</code></td></tr></tbody></table><p><strong>说明：</strong></p><p>在 <code>Addresses</code> 处填写的地址段为 <code>172.16.1.100-172.16.1.200</code> ，表示该地址池有 <code>101</code> 个可用 IPv4 地址。</p><p>预留地址部分将用于内网设备的静态 IPv4 地址设置，在内网设备较多的情况下，可根据实际需求加大该地址池的容量。</p><p>当前子网掩码为 <code>/24</code> 即 <code>255.255.255.0</code> ，因此该地址池最大的地址空间为 <code>172.16.1.2-172.16.1.254</code> 。</p><p><img src="/images/router/routeros/p04/add_dhcp_pool.jpeg" alt="创建DHCP地址池" width="1920" height="1040"></p><p>地址池创建完成后，如图所示。</p><p><img src="/images/router/routeros/p04/dhcp_pool_finish.jpeg" alt="DHCP地址池添加完成" width="1200" height="800"></p><h3 id="_1-2-创建-dhcpv4-服务器" tabindex="-1"><a class="header-anchor" href="#_1-2-创建-dhcpv4-服务器"><span>1.2.创建 DHCPv4 服务器</span></a></h3><p>接下来创建 DHCPv4 服务器， 点击左侧导航 <code>IP</code> 菜单的子菜单 <code>DHCP Server</code> ，点击 <code>New</code> 。</p><table><thead><tr><th>参数</th><th>值</th></tr></thead><tbody><tr><td>Name</td><td><code>dhcpv4-server1</code></td></tr><tr><td>Interface</td><td><code>bridge1</code></td></tr><tr><td>Lease Time</td><td><code>1d 00:00:00</code></td></tr><tr><td>Address Pool</td><td><code>dhcpv4-pool1</code></td></tr><tr><td>Bootp Support</td><td><code>none</code></td></tr><tr><td>Comment</td><td><code>defconf: local LAN DHCPv4 server</code></td></tr></tbody></table><p><img src="/images/router/routeros/p04/add_dhcp_server.jpeg" alt="创建DHCP服务器" width="1920" height="1540"></p><p>DHCPv4 服务器创建完成后如图所示。</p><p><img src="/images/router/routeros/p04/dhcp_server_finish.jpeg" alt="DHCP服务器创建完成" width="1800" height="740"></p><p>接下来设置 DHCPv4 服务器网络参数，切换到 <code>Networks</code> 选项卡，点击 <code>New</code> 。</p><table><thead><tr><th>参数</th><th>值</th></tr></thead><tbody><tr><td>Address</td><td><code>172.16.1.0/24</code></td></tr><tr><td>Gateway</td><td><code>172.16.1.1</code></td></tr><tr><td>Netmask</td><td><code>24</code></td></tr><tr><td>DNS Server</td><td><code>172.16.1.1</code></td></tr><tr><td>Domain</td><td><code>fox.internal</code> (可选)</td></tr><tr><td>Comment</td><td><code>defconf: local LAN DHCPv4 network</code></td></tr></tbody></table><p><img src="/images/router/routeros/p04/add_dhcp_server_network.jpeg" alt="创建DHCP服务器网络" width="1920" height="1230"></p><p>DHCPv4 服务器网络参数设置完成后，如图所示。</p><p><img src="/images/router/routeros/p04/dhcp_server_network_finish.jpeg" alt="DHCP服务器网络创建完成" width="1800" height="740"></p><p>此时重连一次电脑的网络，电脑将能够从 RouterOS 获取到 IPv4 地址。</p><p><img src="/images/router/routeros/p04/pc_dhcp_status.jpeg" alt="电脑正确获取IP地址" width="1840" height="1000"></p><h2 id="_2-dhcpv4-使用内网-dns" tabindex="-1"><a class="header-anchor" href="#_2-dhcpv4-使用内网-dns"><span>2. DHCPv4 使用内网 DNS</span></a></h2><p>在根据我的系列文章 <a href="https://gitee.com/callmer/agh_toss_notes" target="_blank" rel="noopener noreferrer">Adguard Home 折腾手记</a> 安装并配置了内网 DNS 服务器后，需要调整 DHCPv4 服务器的参数。</p><p>点击左侧导航 <code>IP</code> 菜单的子菜单 <code>DHCP Server</code> ，切换到 <code>Networks</code> 选项卡。</p><p><img src="/images/router/routeros/p04/dhcp_server_network_modify.jpeg" alt="修改DHCP服务器" width="1920" height="1020"></p><p>鼠标 <strong>双击</strong> 下方的网络参数条目，进入配置界面。</p><p>在配置界面中，修改 <code>DNS Servers</code> 参数为内网两台 DNS 服务器的 IPv4 地址。</p><p>演示中，内网的 DNS 服务器 IPv4 地址为 <code>172.16.1.2</code> 和 <code>172.16.1.3</code> 。</p><p><img src="/images/router/routeros/p04/dhcp_server_network_modify_dns.jpeg" alt="DHCP服务器配置内网DNS" width="1840" height="1270"></p><p>DHCPv4 服务器网络参数修改完成后，如图所示。</p><p><img src="/images/router/routeros/p04/dhcp_server_network_modify_finish.jpeg" alt="修改DHCP服务器完成" width="1840" height="740"></p><h2 id="_3-dhcpv4-options" tabindex="-1"><a class="header-anchor" href="#_3-dhcpv4-options"><span>3. DHCPv4 Options</span></a></h2><p>通过设置 DHCPv4 的 <code>Options</code> 参数，可以让内网设备从 DHCPv4 服务器中获取指定的 <code>网关地址</code> 和 <code>DNS 地址</code> 。</p><p>演示用的 IPv4 地址均为 <code>172.16.1.50</code> 。</p><p>使用 Winbox 登录 RouterOS ，点击左侧导航 <code>IP</code> 菜单的子菜单 <code>DHCP Server</code> 。</p><p>切换到 <code>Options</code> 选项卡，点击 <code>New</code> 。</p><p>在弹出的 <code>New DHCP Options</code> 对话框中修改 <code>Name</code> 、 <code>Code</code> 、 <code>Value</code> 三个参数。</p><table><thead><tr><th>参数</th><th>值1</th><th>值2</th><th>说明</th></tr></thead><tbody><tr><td>Name</td><td><code>opt-bypass-gw</code></td><td><code>opt-bypass-dnsv4</code></td><td>参数名称，可自定义</td></tr><tr><td>Code</td><td><code>3</code></td><td><code>6</code></td><td><code>3</code> 表示设置网关地址，<code>6</code> 表示设置 DNS 地址</td></tr><tr><td>Value</td><td><code>&#39;172.16.1.50&#39;</code></td><td><code>&#39;172.16.1.50&#39;</code></td><td>填入对应的 IP 地址，需要用 <strong>单引号</strong> 括起来</td></tr></tbody></table><p><img src="/images/router/routeros/p04/add_dhcp_option.jpeg" alt="添加DHCP选项" width="1920" height="1040"></p><p>设置完成后，如下图所示。</p><p><img src="/images/router/routeros/p04/add_dhcp_options_done.jpeg" alt="添加DHCP选项完成" width="1800" height="740"></p><p>切换到 <code>Option Sets</code> 选项卡，点击 <code>New</code> ，新增一个 “参数组” 。</p><p>在弹出的 <code>New DHCP Option Set</code> 对话框中修改 <code>Name</code> 、 <code>Options</code> 两个参数。</p><p>通过 <code>Options</code> 条目右侧按钮，可以添加多个 <code>Option</code> 参数。</p><p><img src="/images/router/routeros/p04/add_dhcp_option_sets.jpeg" alt="添加DHCP选项组" width="1800" height="740"></p><h2 id="_4-dhcpv4-静态地址绑定" tabindex="-1"><a class="header-anchor" href="#_4-dhcpv4-静态地址绑定"><span>4. DHCPv4 静态地址绑定</span></a></h2><p>切换到 <code>Leases</code> 选项卡，点击 <code>New</code> ，新增一个 DHCPv4 静态地址绑定。</p><p>在 <code>New DHCP Lease</code> 对话框中修改参数，参数说明如下。</p><table><thead><tr><th>参数</th><th>值</th><th>说明</th></tr></thead><tbody><tr><td>Address</td><td><code>172.16.1.233</code></td><td>指定的静态 IPv4 地址，需要与 DHCPv4 服务器同网段</td></tr><tr><td>MAC Address</td><td><code>aa:bb:cc:dd:ee:ff</code></td><td>设备的 MAC 地址</td></tr><tr><td>Server</td><td><code>dhcpv4-server1</code></td><td>选择 DHCPv4 服务器</td></tr><tr><td>Lease Time</td><td><code>2d 00:00:00</code></td><td>设备 IPv4 地址租期</td></tr><tr><td>Comment</td><td><code>&lt;your-device-name1&gt;</code></td><td>设备备注信息，用英文填写</td></tr></tbody></table><p><img src="/images/router/routeros/p04/add_static_dhcp.jpeg" alt="添加静态IP地址" width="1800" height="1460"></p><p>点击 <code>OK</code> 后，该设备的静态 IPv4 地址设置完成，让设备重新联网即可获取指定的 IPv4 地址。</p><p>如果需要让该设备使用指定的 DHCPv4 参数，可以修改 <code>DHCP Option Set</code> 参数。</p><p><img src="/images/router/routeros/p04/dhcp_use_option_set.jpeg" alt="设备使用DHCP参数组" width="1800" height="1480"></p><p>或者，逐一修改 <code>DHCP Options</code> 参数。</p><p>区别在于，使用了 <code>DHCP Option Set</code> 后， “参数组” 内的所有 DHCPv4 参数都将应用于该设备。</p><p>使用 <code>DHCP Options</code> 则可以对该设备的 DHCPv4 参数进行精细化设置。</p><p>建议 <code>DHCP Options</code> 和 <code>DHCP Option Set</code> <strong>不要同时使用</strong> 。</p><p>只有配置了 <code>DHCP Options</code> 的内网设备才能获取指定的 DHCPv4 参数，而其他设备不受影响。</p><p><img src="/images/router/routeros/p04/dhcp_use_options.jpeg" alt="设备使用DHCP参数" width="1800" height="1470"></p><p>至此，RouterOS 设置系统 DHCPv4 步骤完成。</p>`,63)])}var f=c(u,[[`render`,d]]);export{l as _pageData,f as default};